// spec: specs/search-filters.md (2.1, 2.2) · кейсы: .qa/tests/search-filters/FILTER-REMOVED-01.md, FILTER-REMOVED-02.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. «מחזור שנתי», «רווח שנתי», «שנות פעילות» убраны «בשלב זה»
// (согласованная просьба клиента, F-21 AC 4 в документации устарел). На карточках выдачи эти слова бывают — проверяется только окно фильтра.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, openPage, openFilter, foundCount, resultIds, rangeLabel, fmt, REMOVED_FILTERS, LEGACY_PARAMS, PRICE_EDGE,
} from './search-filters.helpers';

test.use({ serviceWorkers: 'block' });

const WINDOWS = [
  { path: '/search', tag: '@desktop', popup: false, where: 'боковой фильтр /search' },
  { path: '/mapview', tag: '@desktop', popup: false, where: 'фильтр /mapview' },
  { path: '/search', tag: '@android', popup: true, where: 'попап «חיפוש וסינון» /search' },
  { path: '/mapview', tag: '@android', popup: false, where: 'панель фильтра /mapview' },
];

test.describe('Фильтры поиска — убраны מחזור שנתי / רווח שנתי / שנות פעילות', () => {
  for (const w of WINDOWS) {
    test(`${w.where}: только «טווח מחירים» ₪0–₪10,000,000 с двумя ручками, трёх убранных фильтров нет #b4b8c9 ${w.tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await page.goto(w.path); // мобильная карта не показывает «נמצאו N» до открытия панели
      const scope = await openFilter(page, w.popup);
      await expect(scope.getByText('טווח מחירים', { exact: true })).toBeVisible();
      await expect(rangeLabel(scope)).toHaveText(`₪0 - ${fmt(PRICE_EDGE)}`);
      await expect(scope.getByRole('slider'), 'в окне один ползунок с двумя ручками (Minimum, Maximum)').toHaveCount(2);
      for (const label of REMOVED_FILTERS) await expect(scope.getByText(label), `«${label}» нет в окне фильтра`).toHaveCount(0);
    });
  }

  const LEGACY = [
    { path: '/search', tag: '@desktop' },
    { path: '/mapview', tag: '@desktop' },
    { path: '/search', tag: '@android' },
  ];
  for (const l of LEGACY) {
    test(`Старая ссылка ${l.path}?minRevenue…&maxYears… ничего не фильтрует #b4b8c9 ${l.tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openPage(page, l.path);
      const base = await foundCount(page);
      const baseIds = l.path === '/search' ? await resultIds(page) : [];
      expect(base, 'выдача без параметров не пустая').toBeGreaterThan(0);

      await openPage(page, `${l.path}?${LEGACY_PARAMS}`);
      await expect.poll(() => foundCount(page), { message: '«נמצאו N» как без параметров' }).toBe(base);
      if (l.path === '/search') expect(await resultIds(page), 'те же объявления').toEqual(baseIds);
    });
  }
});
